// composedSignatureChecks builds every check this run derived.
//
// sig is the one shape they share; the literals below state only what
// differs. Falsifiable is Proven wherever a defect rule reached the
// claim, which the parity gate refuses to stamp without one.
func composedSignatureChecks(fx ComposedFixture) []suite.Check[Composed] {
	sig := suite.ProvenCheck[Composed]
	ix := composedCheckIndex
	return []suite.Check[Composed]{
		sig(ix.Get.Smoke(), suite.ClassSmoke,
			"Get survives a call with a seeded key",
			func(tb testing.TB, c Composed) {
				composedAssertGetSmoke(tb, c, fx)
			}),
		sig(ix.Get.Cancels(), suite.ClassCancel,
			"Get reports a cancelled context as cancelled",
			func(tb testing.TB, c Composed) {
				composedAssertGetCancels(tb, c, fx)
			}),
		sig(ix.Get.NilContext(), suite.ClassNilContext,
			"Get returns an error rather than panicking on a nil context",
			func(tb testing.TB, c Composed) {
				composedAssertGetToleratesNilContext(tb, c, fx)
			}),
		sig(ix.Get.Deadline(), suite.ClassDeadline,
			"Get reports an expired deadline as exceeded",
			func(tb testing.TB, c Composed) {
				composedAssertGetHonoursDeadline(tb, c, fx)
			}),
		sig(ix.Get.ZeroOnError(), suite.ClassZeroValue,
			"Get returns zero alongside any error",
			func(tb testing.TB, c Composed) {
				composedAssertGetZeroOnError(tb, c, fx)
			}),
		sig(ix.Ping.Smoke(), suite.ClassSmoke,
			"Ping survives a call",
			func(tb testing.TB, c Composed) {
				composedAssertPingSmoke(tb, c)
			}),
		sig(ix.Ping.Cancels(), suite.ClassCancel,
			"Ping reports a cancelled context as cancelled",
			func(tb testing.TB, c Composed) {
				composedAssertPingCancels(tb, c)
			}),
		sig(ix.Ping.NilContext(), suite.ClassNilContext,
			"Ping returns an error rather than panicking on a nil context",
			func(tb testing.TB, c Composed) {
				composedAssertPingToleratesNilContext(tb, c)
			}),
		sig(ix.Close.Smoke(), suite.ClassSmoke,
			"Close survives a call",
			func(tb testing.TB, c Composed) {
				composedAssertCloseSmoke(tb, c)
			}),
		sig(ix.Close.Cancels(), suite.ClassCancel,
			"Close reports a cancelled context as cancelled",
			func(tb testing.TB, c Composed) {
				composedAssertCloseCancels(tb, c)
			}),
		sig(ix.Close.NilContext(), suite.ClassNilContext,
			"Close returns an error rather than panicking on a nil context",
			func(tb testing.TB, c Composed) {
				composedAssertCloseToleratesNilContext(tb, c)
			}),
		sig(ix.Get.Miss(), suite.ClassReader,
			"Get reports zero for a key nothing has seeded",
			func(tb testing.TB, c Composed) {
				composedAssertGetMiss(tb, c, fx)
			}),
	}
}

