// AssertComposedContract runs every generated check against every declared subject.
//
//	Subjects: declare each with ComposedSubject
//	Extend:   ComposedOnGet, ComposedOnPing, ComposedOnClose
//	Drop:     ComposedWithout, by the path each check reports under
//	Unseeded: every check here runs against a fresh subject, because
//	          no method here is classified as a write.
//	          A read over an empty subject cannot tell a miss from a bug;
//	          ComposedSeed is what closes it.
func AssertComposedContract(t *testing.T, opts ...ComposedOption) {
	t.Helper()
	cfg := newComposedConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertComposedContract was given no subject; declare one with " +
			"ComposedSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("ComposedWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runComposedChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runComposedChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runComposedChecks(
	t *testing.T,
	cfg *composedConfig,
	label string,
	factory func() embedded.Composed,
	wrap func(tb testing.TB, subject embedded.Composed) embedded.Composed,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(composedGet, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onGet {
				cfg.run(t, string(suite.MethodID(composedGet, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
				})
			}
		})

		t.Run(composedPing, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onPing {
				cfg.run(t, string(suite.MethodID(composedPing, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		t.Run(composedClose, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onClose {
				cfg.run(t, string(suite.MethodID(composedClose, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through ComposedWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

// ComposedOption configures a contract run.
type ComposedOption func(*composedConfig)

// ComposedSubject declares an implementation to hold to the contract.
//
// Repeat it for every implementation that claims to satisfy the interface — an
// in-memory one, the one backed by a database, the one behind a network. Every
// check and every option is stated once and runs against all of them, which is
// what a conformance suite is for.
func ComposedSubject(name string, factory func() embedded.Composed) ComposedOption {
	return func(c *composedConfig) {
		c.subjects = append(c.subjects, namedComposedSubject{name, factory})
	}
}

// ComposedWithClock supplies the clock every time-reading check measures on.
//
// Defaults to the real one, so an implementation that does not take a clock
// behaves as it would have. Supply a [clock.TestClock] — the same one the
// factory builds the subject with — and a budget becomes a claim about the time
// the implementation means to spend rather than about how loaded the machine
// was.
func ComposedWithClock(c clock.Clock) ComposedOption {
	return func(cfg *composedConfig) { cfg.clock = c }
}

// ComposedWithFixture replaces the derived inputs.
func ComposedWithFixture(f ComposedFixture) ComposedOption {
	return func(c *composedConfig) { c.Fixture = f }
}

// ComposedSeed replaces the derived seed.
//
// For an interface with no writer to seed itself through, which is the one
// input a conformance run cannot derive: a reader over an empty subject
// asserts nothing.
//
// Returning an error rather than swallowing one. A seed that failed quietly
// leaves every check after it asserting nothing and reporting success.
func ComposedSeed(fn func(ctx context.Context, subject embedded.Composed) error) ComposedOption {
	return func(c *composedConfig) {
		c.seed = fn
	}
}

// ComposedOnGet adds a named check to Get.
func ComposedOnGet(name string, fn ComposedGetCheck) ComposedOption {
	return func(c *composedConfig) {
		c.onGet = append(c.onGet, namedComposedGetCheck{name, fn})
	}
}

// ComposedOnPing adds a named check to Ping.
func ComposedOnPing(name string, fn ComposedPingCheck) ComposedOption {
	return func(c *composedConfig) {
		c.onPing = append(c.onPing, namedComposedPingCheck{name, fn})
	}
}

// ComposedOnClose adds a named check to Close.
func ComposedOnClose(name string, fn ComposedCloseCheck) ComposedOption {
	return func(c *composedConfig) {
		c.onClose = append(c.onClose, namedComposedCloseCheck{name, fn})
	}
}

// ComposedWithout drops generated checks by the path each reports under.
//
// For a subject that legitimately violates one. Without this the only recourse
// is to stop running the suite, which costs every other check in the file — so
// a dropped check is reported as skipped rather than silently omitted.
func ComposedWithout(paths ...string) ComposedOption {
	return func(c *composedConfig) {
		for _, p := range paths {
			c.without[p] = struct{}{}
		}
	}
}

type namedComposedGetCheck struct {
	name string
	fn   ComposedGetCheck
}

type namedComposedPingCheck struct {
	name string
	fn   ComposedPingCheck
}

type namedComposedCloseCheck struct {
	name string
	fn   ComposedCloseCheck
}

type namedComposedSubject struct {
	name    string
	factory func() embedded.Composed
}

// composedContractExtension is a body of checks a generated sibling adds through an option.
//
// A sibling declares the option and closes over whatever configures it, so
// everything that varies per run is typed and private to the file that owns it
// — this file understands only the name and the call. Nothing arrives except
// through an option, which is what keeps the set fixed before the first subtest
// starts.
type composedContractExtension struct {
	// name is the path this reports under, and the one ComposedWithout drops
	// it by. Anything nested beneath it is the extension's own to name.
	name string

	// run takes the factory rather than a subject. One that drives sequences
	// builds a subject per iteration, and one that compares against a reference
	// needs the unseeded subject a factory returns — which
	// composedConfig.subject is not.
	//
	// Called once per subject, in parallel, sharing the config. Anything it
	// mutates has to be built inside the call: state captured when the option
	// was declared is state two subjects write at once.
	run func(
		t *testing.T,
		subject string,
		factory func() embedded.Composed,
		cfg *composedConfig,
	)
}

type composedConfig struct {
	Fixture    ComposedFixture
	subjects   []namedComposedSubject
	clock      clock.Clock
	seed       func(ctx context.Context, subject embedded.Composed) error
	without    map[string]struct{}
	extensions []composedContractExtension
	onGet      []namedComposedGetCheck
	onPing     []namedComposedPingCheck
	onClose    []namedComposedCloseCheck
}

func newComposedConfig(opts ...ComposedOption) *composedConfig {
	c := &composedConfig{
		Fixture: DefaultComposedFixture(),
		clock:   clock.RealClock(),
		without: map[string]struct{}{},
	}
	for _, o := range opts {
		o(c)
	}
	return c
}

// subject builds a fresh implementation and seeds it, so every check runs
// against state no other check touched.
func (c *composedConfig) subject(
	tb testing.TB,
	factory func() embedded.Composed,
	wrap func(tb testing.TB, subject embedded.Composed) embedded.Composed,
) embedded.Composed {
	tb.Helper()
	s := factory()
	if c.seed != nil {
		// Reported rather than ignored. A seed that silently failed would leave
		// every check after it running against an empty subject — passing, and
		// asserting nothing.
		//
		// Which seed ran decides what the message can usefully say. The derived
		// one fails for one of two reasons and both are fixable from here, so it
		// names them. A seed the caller supplied is theirs, and telling them to
		// supply one is advice they already took.
		if err := c.seed(tb.Context(), s); err != nil {
			tb.Fatalf("the seed supplied through ComposedSeed failed: %v", err)
		}
	}
	if wrap != nil {
		s = wrap(tb, s)
	}
	return s
}

// dropped reports whether a path was declined through ComposedWithout.
//
// Named rather than inlined because the drop set is read from two places: here,
// and by whatever registered through the seam — which reports under paths this
// file has never heard of and must answer the same question about them.
func (c *composedConfig) declined(path string) bool {
	_, ok := c.without[path]
	return ok
}

// composedPaths is every path this file reports a check under.
//
// The set a ComposedWithout argument has to be a member of. Declared
// rather than observed: a check that did not run is not a check that does not
// exist — an integration-only method skips without ever consulting the drop
// set, and reading that as a phantom would fail a correct suite on a machine
// with the environment unset.
//
//nolint:gochecknoglobals // the emitted check paths, read-only after init.
var composedPaths = map[string]struct{}{}

// phantoms names every ComposedWithout path that declines nothing.
//
// A drop that drops nothing is this option's silent half: the consumer wrote
// it against a check since renamed, or never emitted for that method at all,
// and every run after reads green while asserting one thing more than its
// author believes. Extensions carry their own names — the seam reports under
// paths this file has never heard of — so they count as known too.
func (c *composedConfig) phantoms() []string {
	known := func(p string) bool {
		if _, ok := composedPaths[p]; ok {
			return true
		}
		for _, e := range c.extensions {
			if e.name == p {
				return true
			}
		}
		for _, on := range c.onGet {
			if string(suite.MethodID(composedGet, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onPing {
			if string(suite.MethodID(composedPing, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onClose {
			if string(suite.MethodID(composedClose, on.name)) == p {
				return true
			}
		}
		return false
	}
	var out []string
	for p := range c.without {
		if !known(p) {
			out = append(out, p)
		}
	}
	slices.Sort(out)
	return out
}

// run executes one check unless it was dropped, reporting the drop rather than
// silently omitting it.
func (c *composedConfig) run(t *testing.T, path, name string, fn func(tb testing.TB)) {
	t.Helper()
	if c.declined(path) {
		t.Run(name, func(t *testing.T) {
			t.Skipf("dropped through ComposedWithout(%q)", path)
		})
		return
	}
	t.Run(name, func(t *testing.T) {
		t.Parallel()
		fn(t)
	})
}

